import type {
  GitHubAdapter,
  GitHubPR,
  GitHubReview,
  GitHubIssue,
  GitHubCheckStatus,
  GitHubPRFiles,
} from './adapter.js'

/**
 * MCP-based GitHub adapter stub.
 *
 * This adapter is designed to be called by the coordinator agent,
 * which has direct access to mcp__github__* tools.
 * The actual MCP calls are made through the Claude Code tool layer.
 *
 * In production, the coordinator agent calls the MCP tools directly.
 * This class provides the typed interface and can be used for testing.
 */
export class McpGitHubAdapter implements GitHubAdapter {
  private callMcp: <T>(tool: string, params: Record<string, unknown>) => Promise<T>

  constructor(mcpCaller: <T>(tool: string, params: Record<string, unknown>) => Promise<T>) {
    this.callMcp = mcpCaller
  }

  async listPullRequests(params: {
    owner: string
    repo: string
    state?: 'open' | 'closed' | 'all'
    base?: string
    page?: number
    perPage?: number
  }): Promise<GitHubPR[]> {
    return this.callMcp<GitHubPR[]>('mcp__github__list_pull_requests', {
      owner: params.owner,
      repo: params.repo,
      state: params.state,
      base: params.base,
      page: params.page,
      per_page: params.perPage,
    })
  }

  async getPullRequest(params: {
    owner: string
    repo: string
    number: number
  }): Promise<GitHubPR> {
    return this.callMcp<GitHubPR>('mcp__github__get_pull_request', {
      owner: params.owner,
      repo: params.repo,
      pull_number: params.number,
    })
  }

  async getPullRequestReviews(params: {
    owner: string
    repo: string
    number: number
  }): Promise<GitHubReview[]> {
    return this.callMcp<GitHubReview[]>('mcp__github__get_pull_request_reviews', {
      owner: params.owner,
      repo: params.repo,
      pull_number: params.number,
    })
  }

  async getPullRequestStatus(params: {
    owner: string
    repo: string
    number: number
  }): Promise<GitHubCheckStatus> {
    return this.callMcp<GitHubCheckStatus>('mcp__github__get_pull_request_status', {
      owner: params.owner,
      repo: params.repo,
      pull_number: params.number,
    })
  }

  async getPullRequestFiles(params: {
    owner: string
    repo: string
    number: number
  }): Promise<GitHubPRFiles[]> {
    return this.callMcp<GitHubPRFiles[]>('mcp__github__get_pull_request_files', {
      owner: params.owner,
      repo: params.repo,
      pull_number: params.number,
    })
  }

  async createPullRequest(params: {
    owner: string
    repo: string
    title: string
    body: string
    head: string
    base: string
    draft?: boolean
  }): Promise<GitHubPR> {
    return this.callMcp<GitHubPR>('mcp__github__create_pull_request', {
      owner: params.owner,
      repo: params.repo,
      title: params.title,
      body: params.body,
      head: params.head,
      base: params.base,
      draft: params.draft ?? true,
    })
  }

  async updatePullRequest(params: {
    owner: string
    repo: string
    number: number
    title?: string
    body?: string
    state?: 'open' | 'closed'
    draft?: boolean
  }): Promise<GitHubPR> {
    return this.callMcp<GitHubPR>('mcp__github__update_pull_request', {
      owner: params.owner,
      repo: params.repo,
      pull_number: params.number,
      title: params.title,
      body: params.body,
      state: params.state,
    })
  }

  async addComment(params: {
    owner: string
    repo: string
    issueNumber: number
    body: string
  }): Promise<void> {
    await this.callMcp<unknown>('mcp__github__add_issue_comment', {
      owner: params.owner,
      repo: params.repo,
      issue_number: params.issueNumber,
      body: params.body,
    })
  }

  async listIssues(params: {
    owner: string
    repo: string
    state?: 'open' | 'closed' | 'all'
    labels?: string
    page?: number
    perPage?: number
  }): Promise<GitHubIssue[]> {
    return this.callMcp<GitHubIssue[]>('mcp__github__list_issues', {
      owner: params.owner,
      repo: params.repo,
      state: params.state,
      labels: params.labels,
      page: params.page,
      per_page: params.perPage,
    })
  }

  async searchIssues(params: {
    query: string
    page?: number
    perPage?: number
  }): Promise<GitHubIssue[]> {
    const result = await this.callMcp<{ items: GitHubIssue[] }>('mcp__github__search_issues', {
      q: params.query,
      page: params.page,
      per_page: params.perPage,
    })
    return result.items ?? (result as unknown as GitHubIssue[])
  }
}
